using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: EF Core 9 no longer uses DateTime.UtcNow in HasData
        // because it's non-deterministic. Use a fixed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating breaking-change fixes ---
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=key",
            "ShopDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF Core 9 Cosmos provider renamed the default
        // discriminator property from "Discriminator" to "$type".
        // For existing documents that already use "Discriminator", explicitly
        // configure the property name to preserve backward compatibility.
        modelBuilder.Entity<Product>(b =>
        {
            b.HasDiscriminator<string>("Discriminator");
            b.ToContainer("Products");
        });
    }

    // Breaking change 2: EF Core 9 removed synchronous Cosmos DB query APIs
    // (ToList, First, Single, etc. throw at runtime). Use async equivalents.
    public async Task<List<Product>> GetExpensiveProductsAsync()
    {
        // BEFORE (EF Core 8 - sync, now throws InvalidOperationException):
        // return Products.Where(p => p.Price > 100).ToList();

        // AFTER (EF Core 9 - must use async):
        return await Products.Where(p => p.Price > 100).ToListAsync();
    }
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public decimal Price { get; set; }
}

