using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // Breaking change: EF Core 9 throws if Migrate() is called inside an
    // explicit transaction. Migrations manage their own transactions.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }
}

